// Processa a data e horário para formato correto do Google Calendar
const dados = $input.first().json;

let nome_lead, telefone_lead, email_lead, data_reuniao, horario_reuniao, produto_interesse, observacoes;

// Se os dados vierem como JSON string no campo "query"
if (dados.query) {
  let parsed;

  // Tenta parsear como JSON
  if (typeof dados.query === 'string') {
    try {
      parsed = JSON.parse(dados.query);
    } catch (e) {
      // Se não for JSON, tenta parsear como "campo: valor, campo: valor"
      parsed = {};
      const regex = /(\w+):\s*"?([^",}]+)"?/g;
      let match;
      while ((match = regex.exec(dados.query)) !== null) {
        parsed[match[1]] = match[2].trim();
      }
    }
  } else {
    parsed = dados.query;
  }

  nome_lead = parsed.nome_lead || parsed.nome || 'Lead';
  telefone_lead = parsed.telefone_lead || parsed.telefone || '';
  email_lead = parsed.email_lead || parsed.email || '';
  data_reuniao = parsed.data_reuniao || parsed.data_preferida || parsed.data || 'amanhã';
  horario_reuniao = parsed.horario_reuniao || parsed.horario_preferido || parsed.horario || '10:00';
  produto_interesse = parsed.produto_interesse || parsed.produto || 'Automação';
  observacoes = parsed.observacoes || '';
} else {
  // Formato normal com campos separados
  nome_lead = dados.nome_lead || 'Lead';
  telefone_lead = dados.telefone_lead || '';
  email_lead = dados.email_lead || '';
  data_reuniao = dados.data_reuniao || dados.data_preferida || 'amanhã';
  horario_reuniao = dados.horario_reuniao || dados.horario_preferido || '10:00';
  produto_interesse = dados.produto_interesse || 'Automação';
  observacoes = dados.observacoes || '';
}

// Função para converter data
function converterData(dataStr, horarioStr) {
  const hoje = new Date();
  let dataFinal;

  const dataLower = (dataStr || 'amanhã').toLowerCase().trim();

  // Verifica se é formato ISO (2026-01-21)
  if (/^\d{4}-\d{2}-\d{2}/.test(dataStr)) {
    const partes = dataStr.split('-');
    dataFinal = new Date(parseInt(partes[0]), parseInt(partes[1]) - 1, parseInt(partes[2]));
  } else if (dataLower.includes('hoje')) {
    dataFinal = new Date(hoje);
  } else if (dataLower.includes('amanhã') || dataLower.includes('amanha')) {
    dataFinal = new Date(hoje);
    dataFinal.setDate(dataFinal.getDate() + 1);
  } else if (dataLower.includes('segunda')) {
    dataFinal = proximoDiaSemana(1);
  } else if (dataLower.includes('terça') || dataLower.includes('terca')) {
    dataFinal = proximoDiaSemana(2);
  } else if (dataLower.includes('quarta')) {
    dataFinal = proximoDiaSemana(3);
  } else if (dataLower.includes('quinta')) {
    dataFinal = proximoDiaSemana(4);
  } else if (dataLower.includes('sexta')) {
    dataFinal = proximoDiaSemana(5);
  } else {
    // Tenta DD/MM/YYYY
    const partes = dataStr.split(/[\/\-]/);
    if (partes.length === 3) {
      if (partes[0].length === 4) {
        dataFinal = new Date(parseInt(partes[0]), parseInt(partes[1]) - 1, parseInt(partes[2]));
      } else {
        dataFinal = new Date(parseInt(partes[2]), parseInt(partes[1]) - 1, parseInt(partes[0]));
      }
    } else {
      dataFinal = proximoDiaUtil();
    }
  }

  // Processa o horário
  let hora = 10, minuto = 0;
  const horarioLower = (horarioStr || '10:00').toLowerCase().trim();

  if (horarioLower.includes('manhã') || horarioLower.includes('manha')) {
    hora = 10;
  } else if (horarioLower.includes('tarde')) {
    hora = 15;
  } else {
    const matchHora = horarioStr.match(/(\d{1,2})[h:](\d{2})?/);
    if (matchHora) {
      hora = parseInt(matchHora[1]);
      minuto = matchHora[2] ? parseInt(matchHora[2]) : 0;
    }
  }

  dataFinal.setHours(hora, minuto, 0, 0);
  return dataFinal;
}

function proximoDiaSemana(diaSemana) {
  const hoje = new Date();
  const diaAtual = hoje.getDay();
  let diasAdicionar = diaSemana - diaAtual;
  if (diasAdicionar <= 0) diasAdicionar += 7;
  const proximoDia = new Date(hoje);
  proximoDia.setDate(proximoDia.getDate() + diasAdicionar);
  return proximoDia;
}

function proximoDiaUtil() {
  const hoje = new Date();
  const proximoDia = new Date(hoje);
  proximoDia.setDate(proximoDia.getDate() + 1);
  while (proximoDia.getDay() === 0 || proximoDia.getDay() === 6) {
    proximoDia.setDate(proximoDia.getDate() + 1);
  }
  return proximoDia;
}

function formatarDataBR(data) {
  const dias = ['Domingo', 'Segunda-feira', 'Terça-feira', 'Quarta-feira', 'Quinta-feira', 'Sexta-feira', 'Sábado'];
  const dia = dias[data.getDay()];
  const dataFormatada = data.toLocaleDateString('pt-BR');
  const horaFormatada = data.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  return `${dia}, ${dataFormatada} às ${horaFormatada}`;
}

const dataInicio = converterData(data_reuniao, horario_reuniao);
const dataFim = new Date(dataInicio);
dataFim.setHours(dataFim.getHours() + 1);

return {
  json: {
    nome_lead,
    telefone_lead,
    email_lead,
    data_reuniao,
    horario_reuniao,
    produto_interesse,
    observacoes,
    startTime: dataInicio.toISOString(),
    endTime: dataFim.toISOString(),
    data_iso: `${dataInicio.getFullYear()}-${String(dataInicio.getMonth() + 1).padStart(2, '0')}-${String(dataInicio.getDate()).padStart(2, '0')}`,
    hora_fmt: `${String(dataInicio.getHours()).padStart(2, '0')}:${String(dataInicio.getMinutes()).padStart(2, '0')}`,
    data_formatada: formatarDataBR(dataInicio),
    titulo_evento: `📞 Call Cloudy Solutions - ${nome_lead}`,
    descricao_evento: `🎯 Reunião de Apresentação\n\n👤 Lead: ${nome_lead}\n📱 Telefone: ${telefone_lead}\n📧 Email: ${email_lead}\n\n💼 Interesse: ${produto_interesse}\n\n📝 Observações: ${observacoes || 'Nenhuma'}\n\n---\nAgendado automaticamente pelo CloudyBot`
  }
};
